/// The rustynail licence (MIT), the Lua.org notice that must accompany it, and the third-party notices
/// (generated by `scripts/gen-notice.py`), embedded at build time.
pub const LICENSE: &str = include_str!("../../../LICENSE");
pub const LICENSE_LUA: &str = include_str!("../../../LICENSE-LUA");
pub const NOTICE: &str = include_str!("../../../NOTICE");

pub const AUTHOR_LINE: &str = "Copyright (c) 2026 Kiran Pashikanti <kpatvt@gmail.com>";

#[cfg(not(rustynail_lua54))]
pub const LUA_SERIES: &str = "5.5";
#[cfg(rustynail_lua54)]
pub const LUA_SERIES: &str = "5.4";

/// Prints the full licence information (`--license`): rustynail's licence, then Lua's notice, then the notices of the
/// third-party crates linked into the binary.
pub fn print_license(prog: &str) {
    use std::io::Write;
    let mut o = std::io::stdout().lock();
    let _ = write!(
        o,
        "{prog} {} -- {AUTHOR_LINE}\n\n\
         ===== rustynail licence (LICENSE) =====\n\n{LICENSE}\n\
         ===== Lua licence (LICENSE-LUA) =====\n\n{LICENSE_LUA}\n\
         ===== Notices (NOTICE): Lua attribution and third-party Rust crates =====\n\n{NOTICE}",
        env!("CARGO_PKG_VERSION")
    );
    let _ = o.flush();
}

/// Write `text` plus a newline to stdout and ignore errors (a closed pipe, `rnlua --version | head -1`): `println!` would
/// panic with `failed printing to stdout`, while the reference `lua` dies silently from SIGPIPE.
pub fn quiet_println(text: &str) {
    use std::io::Write;
    let mut o = std::io::stdout().lock();
    let _ = writeln!(o, "{text}");
    let _ = o.flush();
}
